source=json.loads("{\"backend/services/news_body_excerpt.py\":\"\\\"\\\"\\\"Extract article sentences for list previews, with no AI or network calls.\\n\\nUses the original paragraph order, excluding structured financial tables,\\npublisher boilerplate and unsupported numeric rows. Never invents content.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nfrom html.parser import HTMLParser\\nimport re\\n\\nMAX_PREVIEW_CHARS = 420\\nMAX_SENTENCES = 3\\n_SKIP_START = (\\n    \\\"면책\\\", \\\"법적 고지\\\", \\\"forward-looking statements\\\",\\n    \\\"forward-looking statement\\\", \\\"about \\\", \\\"회사 소개\\\",\\n    \\\"관련 문의\\\", \\\"문의처\\\", \\\"본 보도자료\\\", \\\"본 자료에 포함\\\",\\n)\\n\\n\\nclass _Paragraphs(HTMLParser):\\n    def __init__(self):\\n        super().__init__(convert_charrefs=True)\\n        self.items = []\\n        self._depth = 0\\n        self._excluded = 0\\n        self._chunks = []\\n\\n    def handle_starttag(self, tag, attrs):\\n        if tag in (\\\"table\\\", \\\"script\\\", \\\"style\\\"):\\n            self._excluded += 1\\n        if tag == \\\"p\\\":\\n            self._depth += 1\\n            self._chunks = []\\n\\n    def handle_endtag(self, tag):\\n        if tag == \\\"p\\\" and self._depth:\\n            text = \\\" \\\".join(\\\"\\\".join(self._chunks).split())\\n            if text and not self._excluded:\\n                self.items.append(text)\\n            self._depth -= 1\\n            self._chunks = []\\n        if tag in (\\\"table\\\", \\\"script\\\", \\\"style\\\") and self._excluded:\\n            self._excluded -= 1\\n\\n    def handle_data(self, data):\\n        if self._depth and not self._excluded:\\n            self._chunks.append(data)\\n\\n\\ndef _paragraphs(article):\\n    formatted = article.get(\\\"detail_html\\\")\\n    if article.get(\\\"detail_html_safe\\\") is True and isinstance(formatted, str) and formatted:\\n        parser = _Paragraphs()\\n        parser.feed(formatted)\\n        if parser.items:\\n            return parser.items\\n    body = article.get(\\\"detail_body\\\")\\n    if isinstance(body, str):\\n        return [re.sub(r\\\"\\\\s+\\\", \\\" \\\", part).strip()\\n                for part in re.split(r\\\"\\\\n\\\\s*\\\\n+\\\", body) if part.strip()]\\n    return []\\n\\n\\ndef _suitable(sentence):\\n    candidate = sentence.strip()\\n    lower = candidate.lower()\\n    if len(candidate) < 12 or len(candidate) > 420:\\n        return False\\n    if any(lower.startswith(prefix) for prefix in _SKIP_START):\\n        return False\\n    if re.search(r\\\"\\\\$[\\\\d,]+.*\\\\$[\\\\d,]+.*\\\\$[\\\\d,]+\\\", candidate):\\n        return False\\n    if re.search(r\\\"(?:^|\\\\s)(?:3Q\\\\d\\\\d|FY\\\\d\\\\d|Q[1-4]\\\\d\\\\d)(?=\\\\S)\\\", candidate):\\n        return False\\n    # Skip text that is largely a merged numeric financial table.\\n    if len(re.findall(r\\\"\\\\d+(?:[.,]\\\\d+)*\\\", candidate)) >= 12:\\n        return False\\n    return True\\n\\n\\ndef extract_preview(article):\\n    \\\"\\\"\\\"Pick up to three complete, original article sentences, in source order.\\\"\\\"\\\"\\n    if not isinstance(article, dict):\\n        return \\\"\\\"\\n    sentences = []\\n    for paragraph in _paragraphs(article):\\n        # Sentence boundary: Korean/English period, question mark, exclamation.\\n        # Avoid chopping decimal numbers and prefer intact source sentences.\\n        parts = re.split(r\\\"(?<=[.!?。])\\\\s+(?=[가-힣A-Z0-9“‘\\\\\\\"(])\\\", paragraph)\\n        for sentence in parts:\\n            sentence = re.sub(r\\\"\\\\s+\\\", \\\" \\\", sentence).strip()\\n            if not _suitable(sentence):\\n                continue\\n            if sentence in sentences:\\n                continue\\n            if sum(map(len, sentences)) + len(sentence) + len(sentences) > MAX_PREVIEW_CHARS:\\n                if sentences:\\n                    return \\\" \\\".join(sentences)\\n                continue\\n            sentences.append(sentence)\\n            if len(sentences) >= MAX_SENTENCES:\\n                return \\\" \\\".join(sentences)\\n    return \\\" \\\".join(sentences)\\n\",\"backend/services/tradingview_news_page.py\":\"\\\"\\\"\\\"Build a standalone news-page snapshot from the shared TradingView cache.\\n\\nNo API calls, database writes, or AI calls happen here. The snapshot is a\\nscreen-facing intermediate artifact that can later be copied to R2 unchanged.\\n\\\"\\\"\\\"\\nfrom __future__ import annotations\\n\\nimport datetime as dt\\nimport json\\nimport os\\nfrom pathlib import Path\\nimport re\\nimport tempfile\\n\\nfrom backend.services.news_body_excerpt import extract_preview\\n\\nNEWS_PAGE_PATH = Path(\\\"/var/lib/gaemigtp-news/tradingview-news-page.json\\\")\\nMAX_PAGE_ITEMS = 2000\\n\\n# gaemiGTP's fixed 14 stock-news event taxonomy.\\n# Rules only provide a first-pass page filter. AI interpretation stays separate.\\nCATEGORY_RULES = (\\n    (\\\"guidance\\\", \\\"실적 전망\\\", (\\n        \\\"guidance\\\", \\\"outlook\\\", \\\"forecast\\\", \\\"가이던스\\\", \\\"전망 상향\\\",\\n        \\\"전망 하향\\\", \\\"연간 전망\\\", \\\"매출 전망\\\",\\n    )),\\n    (\\\"earnings\\\", \\\"실적 발표\\\", (\\n        \\\"earnings\\\", \\\"quarterly results\\\", \\\"financial results\\\", \\\"실적 발표\\\",\\n        \\\"실적발표\\\", \\\"어닝\\\", \\\"매출\\\", \\\"영업이익\\\", \\\"순이익\\\", \\\"eps\\\",\\n    )),\\n    (\\\"analyst\\\", \\\"증권사 평가\\\", (\\n        \\\"price target\\\", \\\"target price\\\", \\\"upgrade\\\", \\\"downgrade\\\", \\\"initiates\\\",\\n        \\\"coverage\\\", \\\"rating\\\", \\\"목표주가\\\", \\\"투자의견\\\", \\\"매수의견\\\",\\n        \\\"중립\\\", \\\"비중확대\\\", \\\"증권사\\\",\\n    )),\\n    (\\\"operations\\\", \\\"사업 성과\\\", (\\n        \\\"sales rose\\\", \\\"sales growth\\\", \\\"shipments\\\", \\\"deliveries\\\", \\\"subscribers\\\",\\n        \\\"production\\\", \\\"판매량\\\", \\\"가입자\\\", \\\"생산 확대\\\", \\\"생산량\\\", \\\"출하량\\\",\\n        \\\"점유율\\\", \\\"사업 성과\\\",\\n    )),\\n    (\\\"contract\\\", \\\"계약·수주\\\", (\\n        \\\"contract\\\", \\\"order\\\", \\\"award\\\", \\\"procurement\\\", \\\"수주\\\", \\\"공급계약\\\",\\n        \\\"계약 체결\\\", \\\"계약 해지\\\", \\\"정부 수주\\\", \\\"대형 계약\\\",\\n    )),\\n    (\\\"product\\\", \\\"제품·기술\\\", (\\n        \\\"launches\\\", \\\"unveils\\\", \\\"new product\\\", \\\"chip\\\", \\\"semiconductor\\\",\\n        \\\"technology\\\", \\\"신제품\\\", \\\"출시\\\", \\\"신기술\\\", \\\"반도체 개발\\\", \\\"기술 공개\\\",\\n    )),\\n    (\\\"capital\\\", \\\"재무·주주환원\\\", (\\n        \\\"buyback\\\", \\\"share repurchase\\\", \\\"dividend\\\", \\\"offering\\\", \\\"capital raise\\\",\\n        \\\"자사주\\\", \\\"배당\\\", \\\"유상증자\\\", \\\"증자\\\", \\\"회사채\\\", \\\"채권 발행\\\",\\n    )),\\n    (\\\"corporate\\\", \\\"인수합병·구조조정\\\", (\\n        \\\"acquisition\\\", \\\"acquire\\\", \\\"merger\\\", \\\"m&a\\\", \\\"spin-off\\\", \\\"spinoff\\\",\\n        \\\"divest\\\", \\\"restructuring\\\", \\\"인수\\\", \\\"합병\\\", \\\"매각\\\", \\\"분사\\\", \\\"구조조정\\\",\\n    )),\\n    (\\\"legal\\\", \\\"법률·사고\\\", (\\n        \\\"lawsuit\\\", \\\"sued\\\", \\\"litigation\\\", \\\"recall\\\", \\\"breach\\\", \\\"cyberattack\\\",\\n        \\\"outage\\\", \\\"accident\\\", \\\"소송\\\", \\\"리콜\\\", \\\"보안 사고\\\", \\\"해킹\\\", \\\"사고\\\",\\n    )),\\n    (\\\"regulation\\\", \\\"인허가·규제\\\", (\\n        \\\"fda\\\", \\\"approval\\\", \\\"approved\\\", \\\"rejects\\\", \\\"rejected\\\", \\\"ban\\\",\\n        \\\"regulator\\\", \\\"antitrust\\\", \\\"승인\\\", \\\"승인 거절\\\", \\\"판매 금지\\\", \\\"인허가\\\",\\n        \\\"규제 당국\\\",\\n    )),\\n    (\\\"flow\\\", \\\"종목별 수급\\\", (\\n        \\\"short interest\\\", \\\"short selling\\\", \\\"institutional buying\\\",\\n        \\\"institutional selling\\\", \\\"공매도\\\", \\\"기관 순매수\\\", \\\"기관 순매도\\\",\\n        \\\"순매수\\\", \\\"순매도\\\", \\\"수급\\\",\\n    )),\\n    (\\\"rnd_clinical\\\", \\\"연구개발·임상\\\", (\\n        \\\"clinical trial\\\", \\\"phase 1\\\", \\\"phase 2\\\", \\\"phase 3\\\", \\\"trial results\\\",\\n        \\\"study results\\\", \\\"research\\\", \\\"임상\\\", \\\"3상\\\", \\\"2상\\\", \\\"1상\\\", \\\"신약\\\",\\n        \\\"연구 결과\\\", \\\"효능\\\",\\n    )),\\n    (\\\"partnership_supplychain\\\", \\\"제휴·공급망\\\", (\\n        \\\"partnership\\\", \\\"partners with\\\", \\\"collaboration\\\", \\\"supply chain\\\",\\n        \\\"supplier\\\", \\\"supply disruption\\\", \\\"제휴\\\", \\\"협력\\\", \\\"파트너십\\\",\\n        \\\"공급망\\\", \\\"공급 차질\\\", \\\"고객사\\\",\\n    )),\\n    (\\\"governance\\\", \\\"경영진·지배구조\\\", (\\n        \\\"ceo\\\", \\\"cfo\\\", \\\"chairman\\\", \\\"board\\\", \\\"director\\\", \\\"management change\\\",\\n        \\\"activist\\\", \\\"proxy fight\\\", \\\"경영권\\\", \\\"경영진\\\", \\\"ceo 교체\\\", \\\"이사회\\\",\\n        \\\"대표이사\\\",\\n    )),\\n)\\n\\nMARKET_RULES = (\\n    (\\\"market\\\", \\\"미국증시\\\", (\\\"stock market\\\", \\\"wall street\\\", \\\"equities\\\", \\\"stocks\\\", \\\"증시\\\", \\\"주식시장\\\")),\\n    (\\\"economic\\\", \\\"경제지표\\\", (\\\"cpi\\\", \\\"pce\\\", \\\"gdp\\\", \\\"jobs\\\", \\\"payroll\\\", \\\"employment\\\", \\\"inflation\\\", \\\"retail sales\\\", \\\"pmi\\\", \\\"경제지표\\\", \\\"고용\\\", \\\"물가\\\", \\\"소비자물가\\\",\\n        \\\"ppi\\\", \\\"adp\\\", \\\"jolts\\\", \\\"ism\\\", \\\"jobless claims\\\", \\\"unemployment claims\\\", \\\"initial claims\\\", \\\"job openings\\\", \\\"consumer confidence\\\", \\\"consumer sentiment\\\", \\\"productivity\\\", \\\"실업수당\\\", \\\"구인건수\\\", \\\"생산성\\\", \\\"소비자심리\\\", \\\"소비자신뢰\\\", \\\"생산자물가\\\", \\\"비농업고용\\\", \\\"실업률\\\", \\\"고용보고서\\\", \\\"소매판매\\\"\\n    )),\\n    (\\\"fed\\\", \\\"연준·금리\\\", (\\\"federal reserve\\\", \\\"fed \\\", \\\"fomc\\\", \\\"powell\\\", \\\"rate cut\\\", \\\"rate hike\\\", \\\"연준\\\", \\\"파월\\\", \\\"금리 인하\\\", \\\"금리 인상\\\",\\n        \\\"central bank\\\", \\\"european central bank\\\", \\\"bank of england\\\", \\\"bank of japan\\\", \\\"lagarde\\\", \\\"bailey\\\", \\\"ueda\\\", \\\"waller\\\", \\\"williams\\\", \\\"hammack\\\", \\\"barkin\\\", \\\"bowman\\\", \\\"goolsbee\\\", \\\"daly\\\", \\\"라가르드\\\", \\\"베일리\\\", \\\"우에다\\\", \\\"월러\\\", \\\"윌리엄스\\\", \\\"해맥\\\", \\\"바킨\\\", \\\"보먼\\\", \\\"굴스비\\\", \\\"연은 총재\\\", \\\"금리 동결\\\", \\\"기준금리\\\", \\\"점도표\\\", \\\"연준 의사록\\\", \\\"양적긴축\\\", \\\"양적완화\\\", \\\"매파\\\", \\\"비둘기파\\\"\\n    )),\\n    (\\\"policy\\\", \\\"정책·규제\\\", (\\\"white house\\\", \\\"congress\\\", \\\"treasury\\\", \\\"administration\\\", \\\"government\\\", \\\"policy\\\", \\\"정부\\\", \\\"정책\\\", \\\"백악관\\\", \\\"의회\\\",\\n        \\\"trump\\\", \\\"hassett\\\", \\\"트럼프\\\", \\\"해싯\\\", \\\"수출통제\\\", \\\"수출 제한\\\", \\\"수출규제\\\", \\\"반독점\\\", \\\"보조금\\\", \\\"재무장관\\\", \\\"백악관 발표\\\"\\n    )),\\n    (\\\"rates_bonds\\\", \\\"연준·금리\\\", (\\\"treasury yield\\\", \\\"bond yield\\\", \\\"10-year\\\", \\\"2-year\\\", \\\"yield curve\\\", \\\"interest rate\\\", \\\"국채금리\\\", \\\"채권금리\\\", \\\"10년물\\\", \\\"2년물\\\", \\\"수익률곡선\\\")),\\n    (\\\"energy\\\", \\\"환율·원자재\\\", (\\\"oil\\\", \\\"crude\\\", \\\"opec\\\", \\\"natural gas\\\", \\\"energy\\\", \\\"원유\\\", \\\"유가\\\", \\\"천연가스\\\", \\\"에너지\\\")),\\n    (\\\"fx_commodities\\\", \\\"환율·원자재\\\", (\\\"dollar index\\\", \\\"dxy\\\", \\\"exchange rate\\\", \\\"forex\\\", \\\"currency\\\", \\\"달러지수\\\", \\\"환율\\\", \\\"엔화\\\", \\\"유로화\\\")),\\n    (\\\"tariff\\\", \\\"정책·규제\\\", (\\\"tariff\\\", \\\"trade war\\\", \\\"import duty\\\", \\\"관세\\\", \\\"무역전쟁\\\")),\\n    (\\\"market_close\\\", \\\"미국증시\\\", (\\\"market close\\\", \\\"closing bell\\\", \\\"closed higher\\\", \\\"closed lower\\\", \\\"마감\\\", \\\"종가\\\")),\\n    (\\\"major_index\\\", \\\"미국증시\\\", (\\\"s&p 500\\\", \\\"nasdaq\\\", \\\"dow jones\\\", \\\"dow \\\", \\\"index\\\", \\\"나스닥\\\", \\\"다우\\\", \\\"s&p\\\")),\\n    (\\\"sector\\\", \\\"산업·섹터\\\", (\\\"sector\\\", \\\"semiconductor stocks\\\", \\\"tech stocks\\\", \\\"financial stocks\\\", \\\"energy stocks\\\", \\\"healthcare stocks\\\", \\\"섹터\\\", \\\"업종\\\", \\\"반도체주\\\", \\\"기술주\\\", \\\"금융주\\\", \\\"에너지주\\\", \\\"헬스케어주\\\")),\\n    (\\\"volatility_sentiment\\\", \\\"수급·변동성\\\", (\\\"vix\\\", \\\"volatility\\\", \\\"fear gauge\\\", \\\"risk appetite\\\", \\\"risk-on\\\", \\\"risk-off\\\", \\\"investor sentiment\\\", \\\"변동성\\\", \\\"공포지수\\\", \\\"위험선호\\\", \\\"위험회피\\\", \\\"투자심리\\\",\\n        \\\"net inflows\\\", \\\"net outflows\\\", \\\"fund inflows\\\", \\\"fund outflows\\\", \\\"capital flows\\\", \\\"money market fund\\\", \\\"mmf\\\", \\\"liquidity\\\", \\\"credit spread\\\", \\\"credit default\\\", \\\"default risk\\\", \\\"short selling\\\", \\\"short interest\\\", \\\"institutional buying\\\", \\\"institutional selling\\\", \\\"자금 유입\\\", \\\"자금 유출\\\", \\\"자금유입\\\", \\\"자금유출\\\", \\\"기관 순매수\\\", \\\"기관 순매도\\\", \\\"순매수\\\", \\\"순매도\\\", \\\"공매도\\\", \\\"유동성\\\", \\\"신용스프레드\\\", \\\"신용 스프레드\\\", \\\"채무불이행\\\", \\\"국채 입찰\\\", \\\"옵션 만기\\\"\\n    )),\\n    (\\\"international\\\", \\\"국제정세\\\", (\\\"middle east\\\", \\\"iran\\\", \\\"war\\\", \\\"sanction\\\", \\\"geopolitical\\\", \\\"중동\\\", \\\"이란\\\", \\\"전쟁\\\", \\\"제재\\\", \\\"지정학\\\")),\\n)\\n\\n\\ndef _text(value):\\n    return re.sub(r\\\"\\\\s+\\\", \\\" \\\", str(value or \\\"\\\")).strip()\\n\\n\\ndef _article_body(value):\\n    \\\"\\\"\\\"Preserve API paragraphs and remove clearly identified publisher boilerplate.\\\"\\\"\\\"\\n    if not isinstance(value, str):\\n        return \\\"\\\"\\n    body = re.sub(r\\\"[ \\\\t]+\\\", \\\" \\\", value.replace(\\\"\\\\r\\\\n\\\", \\\"\\\\n\\\").replace(\\\"\\\\r\\\", \\\"\\\\n\\\")).strip()\\n    body = re.sub(\\n        r\\\"\\\\s*\\\\(로이터는 영어 원어민이 아닌 독자들의 편의를 위해[\\\\s\\\\S]*?\\\"\\n        r\\\"로이터는 완전 자동화된 번역 기능 사용으로 인한 어떠한 종류의 손해나 손실에 대해 \\\"\\n        r\\\"어떠한 책임도 지지 않습니다\\\\.\\\\)\\\\s*$\\\",\\n        \\\"\\\", body,\\n    ).strip()\\n    if not body:\\n        return \\\"\\\"\\n    if \\\"\\\\n\\\" in body:\\n        return re.sub(r\\\"\\\\n[ \\\\t]*\\\\n+\\\", \\\"\\\\n\\\\n\\\", body)\\n    sentences = re.split(r'(?<=[.!?]) +(?=[가-힣A-Z“‘\\\"(])', body)\\n    if len(sentences) < 2:\\n        return body\\n    paragraphs = []\\n    group = []\\n    for sentence in sentences:\\n        if group and (len(group) >= 2 or sum(map(len, group)) > 350):\\n            paragraphs.append(\\\" \\\".join(group))\\n            group = []\\n        group.append(sentence)\\n    if group:\\n        paragraphs.append(\\\" \\\".join(group))\\n    return \\\"\\\\n\\\\n\\\".join(paragraphs)\\n\\n\\ndef _has_us_equity_symbol(article):\\n    related = article.get(\\\"relatedSymbols\\\") or article.get(\\\"related_symbols\\\") or []\\n    if not isinstance(related, list):\\n        return False\\n    for entry in related:\\n        if not isinstance(entry, dict):\\n            continue\\n        symbol = str(entry.get(\\\"symbol\\\") or \\\"\\\").upper()\\n        if symbol.startswith((\\\"NASDAQ:\\\", \\\"NYSE:\\\", \\\"AMEX:\\\", \\\"NYSEARCA:\\\", \\\"NYSEAMERICAN:\\\", \\\"BATS:\\\")):\\n            return True\\n    return False\\n\\n\\ndef classify_article(article):\\n    haystack = _text(article.get(\\\"title\\\")).lower()\\n    source_categories = article.get(\\\"news_categories\\\") or []\\n    if not isinstance(source_categories, list):\\n        source_categories = []\\n\\n    stock_source = \\\"stock\\\" in source_categories or (\\n        \\\"overall\\\" in source_categories and _has_us_equity_symbol(article)\\n    )\\n    stock_matches = [\\n        {\\\"code\\\": code, \\\"label\\\": label}\\n        for code, label, terms in CATEGORY_RULES\\n        if any(str(term).lower() in haystack for term in terms)\\n    ] if stock_source else []\\n    # The overall feed also carries company news. Prefer the title; if a\\n    # symbol-linked company headline has no event keyword, check its supplied\\n    # short description instead of dropping it before stock classification.\\n    # Do not use the full article body for keyword matching.\\n    if stock_source and not stock_matches:\\n        description = _text(\\n            article.get(\\\"shortDescription\\\")\\n            or article.get(\\\"detail_description\\\")\\n            or article.get(\\\"description\\\")\\n            or article.get(\\\"summary\\\")\\n        ).lower()\\n        if description:\\n            stock_matches = [\\n                {\\\"code\\\": code, \\\"label\\\": label}\\n                for code, label, terms in CATEGORY_RULES\\n                if any(str(term).lower() in description for term in terms)\\n            ]\\n    # A stock-feed article or an overall article linked to a US equity\\n    # is eligible for the same 14 stock-event categories.\\n    if stock_source:\\n        if stock_matches:\\n            return stock_matches[0], stock_matches, \\\"stock\\\"\\n        # Only unclassified events are excluded, not the whole overall feed.\\n        return {\\\"code\\\": \\\"other\\\", \\\"label\\\": \\\"기타\\\"}, [], \\\"other\\\"\\n\\n    # Specific market events take precedence over generic market terms.\\n    market_matches = [\\n        {\\\"code\\\": code, \\\"label\\\": label}\\n        for code, label, terms in MARKET_RULES\\n        if any(str(term).lower() in haystack for term in terms)\\n    ]\\n    specific = [match for match in market_matches\\n                if match[\\\"code\\\"] not in (\\\"market\\\", \\\"sector\\\")]\\n    if specific:\\n        return specific[0], market_matches, \\\"market\\\"\\n    if \\\"economic\\\" in source_categories:\\n        return {\\\"code\\\": \\\"economic\\\", \\\"label\\\": \\\"경제지표\\\"}, market_matches, \\\"market\\\"\\n    if \\\"index\\\" in source_categories:\\n        return {\\\"code\\\": \\\"major_index\\\", \\\"label\\\": \\\"주요지수\\\"}, market_matches, \\\"market\\\"\\n    if market_matches:\\n        return market_matches[0], market_matches, \\\"market\\\"\\n    return {\\\"code\\\": \\\"other\\\", \\\"label\\\": \\\"기타\\\"}, [], \\\"other\\\"\\n\\n\\ndef _symbols(article):\\n    rows = article.get(\\\"relatedSymbols\\\") or article.get(\\\"related_symbols\\\") or []\\n    result = []\\n    if isinstance(rows, list):\\n        for row in rows:\\n            if not isinstance(row, dict):\\n                continue\\n            raw = _text(row.get(\\\"symbol\\\"))\\n            if not raw:\\n                continue\\n            ticker = raw.rsplit(\\\":\\\", 1)[-1].upper()\\n            if ticker and ticker not in result:\\n                result.append(ticker)\\n    return result\\n\\n\\ndef _published_iso(article):\\n    value = article.get(\\\"published\\\")\\n    try:\\n        return dt.datetime.fromtimestamp(\\n            float(value), dt.timezone.utc\\n        ).isoformat()\\n    except (TypeError, ValueError, OverflowError, OSError):\\n        return \\\"\\\"\\n\\n\\ndef _news_url(article):\\n    story_path = _text(article.get(\\\"storyPath\\\"))\\n    if story_path.startswith(\\\"/news/\\\"):\\n        return \\\"https://www.tradingview.com\\\" + story_path\\n    return \\\"\\\"\\n\\n\\ndef normalize_article(article):\\n    primary, matches, section = classify_article(article)\\n    # A news item keeps one ID while carrying both market and stock tags.\\n    market_matches = matches if section == \\\"market\\\" else [\\n        {\\\"code\\\": code, \\\"label\\\": label}\\n        for code, label, terms in MARKET_RULES\\n        if any(str(term).lower() in _text(article.get(\\\"title\\\")).lower() for term in terms)\\n    ]\\n    market_evidence = [\\n        item for item in market_matches\\n        if item[\\\"code\\\"] not in (\\\"market\\\",)\\n    ]\\n    if section == \\\"other\\\" and market_evidence:\\n        primary, matches, section = market_evidence[0], market_matches, \\\"market\\\"\\n    stock_matches = matches if section == \\\"stock\\\" else []\\n    market_primary = (\\n        next((m for m in market_matches\\n              if m[\\\"code\\\"] not in (\\\"market\\\", \\\"sector\\\")), None)\\n        or (market_evidence[0] if market_evidence else None)\\n        or (primary if section == \\\"market\\\" else None)\\n    )\\n    news_sections = [\\\"stock\\\"] if section == \\\"stock\\\" else []\\n    if section == \\\"market\\\" or (section == \\\"stock\\\" and market_evidence):\\n        news_sections.append(\\\"market\\\")\\n    provider = article.get(\\\"provider\\\")\\n    source = (\\n        _text(provider.get(\\\"name\\\"))\\n        if isinstance(provider, dict)\\n        else \\\"TradingView\\\"\\n    ) or \\\"TradingView\\\"\\n    # An API response containing article text is not proof of\\n    # republication rights. Keep full text private by default.\\n    may_publish_body = (\\n        article.get(\\\"detail_publication_allowed\\\") is True\\n        and (\\n            article.get(\\\"detail_rights_confirmed\\\") is True\\n            or (article.get(\\\"permission\\\") != \\\"headline\\\"\\n                and article.get(\\\"detail_permission\\\") != \\\"headline\\\")\\n        )\\n    )\\n    body = _article_body(article.get(\\\"detail_body\\\"))\\n    # Only our detail parser produces escaped, allowlisted markup. A random\\n    # provider HTML field must never be copied to the public R2 snapshot.\\n    body_html = (\\n        article.get(\\\"detail_html\\\", \\\"\\\")\\n        if article.get(\\\"detail_html_safe\\\") is True\\n        and isinstance(article.get(\\\"detail_html\\\"), str)\\n        else \\\"\\\"\\n    )\\n    return {\\n        \\\"id\\\": article.get(\\\"id\\\") or article.get(\\\"newsId\\\"),\\n        \\\"published_at\\\": _published_iso(article),\\n        \\\"title\\\": _text(article.get(\\\"title\\\")),\\n        # Compatibility display field for the existing Pages news-card renderer.\\n        # This is an API excerpt, not an AI-generated summary.\\n        \\\"summary\\\": _text(article.get(\\\"detail_summary\\\") or article.get(\\\"summary\\\") or article.get(\\\"shortDescription\\\") or article.get(\\\"detail_description\\\")),\\n        # Preserve the original API detail excerpt separately from a true summary.\\n        \\\"description\\\": _text(article.get(\\\"shortDescription\\\") or article.get(\\\"detail_description\\\")),\\n\\n\\n        \\\"content_source\\\": \\\"api_detail\\\" if article.get(\\\"detail_checked\\\") else \\\"news_list\\\",\\n        \\\"body_available\\\": bool(body or body_html) and may_publish_body,\\n        \\\"body\\\": body if may_publish_body else \\\"\\\",\\n        \\\"body_html\\\": body_html if may_publish_body else \\\"\\\",\\n        \\\"list_excerpt\\\": extract_preview(article) if may_publish_body else \\\"\\\",\\n        \\\"detail_status\\\": _text(article.get(\\\"detail_checked\\\")),\\n        # Full source article bodies are never copied into publicly readable Pages JSON.\\n        \\\"source\\\": source,\\n        \\\"url\\\": _news_url(article),\\n        \\\"symbols\\\": _symbols(article),\\n        \\\"event_category\\\": primary,\\n        \\\"event_matches\\\": matches,\\n        \\\"news_section\\\": section,\\n        \\\"news_sections\\\": news_sections,\\n        \\\"stock_event_matches\\\": stock_matches,\\n        \\\"market_event_category\\\": market_primary,\\n        \\\"market_event_matches\\\": market_matches if \\\"market\\\" in news_sections else [],\\n        \\\"source_categories\\\": article.get(\\\"news_categories\\\") or [],\\n        \\\"paywall\\\": article.get(\\\"paywall\\\"),\\n        \\\"permission\\\": article.get(\\\"permission\\\"),\\n        \\\"provider\\\": \\\"tradingview\\\",\\n    }\\n\\n\\ndef build_snapshot(items, *, generated_at=None):\\n    rows = []\\n    seen = set()\\n    for article in list(items or []):\\n        if not isinstance(article, dict):\\n            continue\\n        row = normalize_article(article)\\n        if not row[\\\"title\\\"] or row[\\\"event_category\\\"][\\\"code\\\"] == \\\"other\\\":\\n            continue\\n        key = str(row[\\\"id\\\"] or \\\"\\\") or (\\n            row[\\\"published_at\\\"] + \\\"|\\\" + row[\\\"title\\\"]\\n        )\\n        if key in seen:\\n            continue\\n        seen.add(key)\\n        rows.append(row)\\n        if len(rows) >= MAX_PAGE_ITEMS:\\n            break\\n\\n    stamp = generated_at or dt.datetime.now(dt.timezone.utc).isoformat()\\n    counts = {}\\n    for row in rows:\\n        code = row[\\\"event_category\\\"][\\\"code\\\"]\\n        counts[code] = counts.get(code, 0) + 1\\n    return {\\n        \\\"ok\\\": True,\\n        \\\"generated_at\\\": stamp,\\n        \\\"source\\\": \\\"tradingview\\\",\\n        \\\"taxonomy\\\": \\\"gaemigtp-stock-events-v1\\\",\\n        \\\"count\\\": len(rows),\\n        \\\"category_counts\\\": counts,\\n        \\\"items\\\": rows,\\n    }\\n\\n\\ndef write_snapshot(items, *, path=NEWS_PAGE_PATH):\\n    snapshot = build_snapshot(items)\\n    path = Path(path)\\n    if not path.parent.is_dir() or path.parent.is_symlink() or path.is_symlink():\\n        raise ValueError(\\\"unsafe_news_page_path\\\")\\n    name = None\\n    try:\\n        with tempfile.NamedTemporaryFile(\\n            mode=\\\"w\\\", encoding=\\\"utf-8\\\", dir=str(path.parent),\\n            prefix=\\\".tv-news-page-\\\", delete=False,\\n        ) as f:\\n            name = f.name\\n            os.fchmod(f.fileno(), 0o600)\\n            json.dump(snapshot, f, ensure_ascii=False, separators=(\\\",\\\", \\\":\\\"))\\n            f.flush()\\n            os.fsync(f.fileno())\\n        os.replace(name, path)\\n    finally:\\n        if name and os.path.exists(name):\\n            os.unlink(name)\\n    return snapshot\\n\",\"tests/test_news_body_excerpt.py\":\"\\\"\\\"\\\"Offline regression tests for article-list sentence extraction.\\\"\\\"\\\"\\nimport unittest\\n\\nfrom backend.services.news_body_excerpt import extract_preview\\nfrom backend.services.tradingview_news_page import normalize_article\\n\\n\\nclass ArticleExcerptTests(unittest.TestCase):\\n    def test_paragraphs_from_ast_exclude_financial_tables(self):\\n        article = {\\n            \\\"detail_html_safe\\\": True,\\n            \\\"detail_html\\\": (\\n                \\\"<p>회사는 2026년 3분기 실적을 발표했다.</p>\\\"\\n                '<div class=\\\"article-table-scroll\\\"><table><tbody><tr>'\\n                \\\"<td>Net sales$1,792 $1,816</td><td>$2.23</td>\\\"\\n                \\\"</tr></tbody></table></div>\\\"\\n                \\\"<p>해외 사업부의 판매량은 작년보다 증가했다.</p>\\\"\\n                \\\"<p>경영진은 다음 분기 수요가 증가할 것으로 전망했다.</p>\\\"\\n            ),\\n            \\\"detail_body\\\": \\\"금액이 붙은 오래된 텍스트\\\",\\n        }\\n        result = extract_preview(article)\\n        self.assertIn(\\\"3분기 실적\\\", result)\\n        self.assertIn(\\\"판매량\\\", result)\\n        self.assertNotIn(\\\"Net sales\\\", result)\\n        self.assertNotIn(\\\"$1,792\\\", result)\\n\\n    def test_generic_articles_use_same_extractor(self):\\n        articles = [\\n            {\\\"detail_body\\\": \\\"미국 연방준비제도는 새 금리 결정을 발표했다. 위원들은 경제 상황을 설명했다.\\\"},\\n            {\\\"detail_body\\\": \\\"회사는 새로운 파트너십을 발표했다. 양사는 공동으로 서비스를 제공한다.\\\"},\\n            {\\\"detail_body\\\": \\\"국제 스포츠 행사가 오늘 시작됐다. 주최 측은 참가자 명단을 공개했다.\\\"},\\n        ]\\n        for row in articles:\\n            with self.subTest(row=row[\\\"detail_body\\\"][:10]):\\n                self.assertTrue(extract_preview(row))\\n\\n    def test_missing_article_never_invents_sentences(self):\\n        self.assertEqual(extract_preview({\\\"title\\\": \\\"제목만 있음\\\"}), \\\"\\\")\\n        self.assertEqual(extract_preview({\\\"detail_body\\\": \\\"\\\"}), \\\"\\\")\\n\\n    def test_public_snapshot_requires_existing_publication_rights(self):\\n        article = {\\n            \\\"id\\\": \\\"sample\\\",\\n            \\\"title\\\": \\\"회사, 신규 기술 공개\\\",\\n            \\\"news_categories\\\": [\\\"stock\\\"],\\n            \\\"detail_body\\\": \\\"회사는 신규 기술을 공개했다고 밝혔다. 제품 출시는 내년에 진행될 예정이다.\\\",\\n        }\\n        blocked = normalize_article(article)\\n        self.assertEqual(blocked[\\\"list_excerpt\\\"], \\\"\\\")\\n        article[\\\"detail_publication_allowed\\\"] = True\\n        article[\\\"detail_rights_confirmed\\\"] = True\\n        allowed = normalize_article(article)\\n        self.assertTrue(allowed[\\\"list_excerpt\\\"])\\n\\n    def test_no_truncated_sentences(self):\\n        article = {\\\"detail_body\\\": (\\n            \\\"회사는 신규 물류센터를 설립한다고 발표했다. \\\"\\n            \\\"물류센터에서는 여러 종류의 상품을 취급한다. \\\"\\n            \\\"향후 인력 채용도 진행한다고 설명했다.\\\"\\n        )}\\n        preview = extract_preview(article)\\n        self.assertLessEqual(len(preview), 420)\\n        self.assertEqual(preview.count(\\\"다.\\\"), 3)\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    unittest.main()\\n\"}")
